void fillPixelBufferRect(const Rect& r, const void* pix) {
    // Check if the rectangle is within bounds and adjust if necessary
    Rect adjustedRect = r;
    if (adjustedRect.left < 0) adjustedRect.left = 0;
    if (adjustedRect.top < 0) adjustedRect.top = 0;
    if (adjustedRect.right > bufferWidth) adjustedRect.right = bufferWidth;
    if (adjustedRect.bottom > bufferHeight) adjustedRect.bottom = bufferHeight;

    // If the adjusted rectangle is empty, return
    if (adjustedRect.left >= adjustedRect.right || adjustedRect.top >= adjustedRect.bottom) {
        return;
    }

    int width = adjustedRect.right - adjustedRect.left;
    int height = adjustedRect.bottom - adjustedRect.top;
    int bytesPerPixel = 4; // Assuming 4 bytes per pixel (RGBA)

    // Iterate over the rectangle and fill the pixel buffer
    for (int y = adjustedRect.top; y < adjustedRect.bottom; ++y) {
        for (int x = adjustedRect.left; x < adjustedRect.right; ++x) {
            memcpy(&pixelBuffer[y][x * bytesPerPixel], pix, bytesPerPixel);
        }
    }

    // Commit changes (e.g., mark buffer as dirty or refresh display)
    commitPixelBuffer();
}

void fillRect(const Rect& r, const void* pix) {
    if (r.isEmpty())
        return;

    // Calculate adjusted rectangle within the buffer bounds
    Rect adjustedRect = r.intersect(getBufferBounds());
    if (adjustedRect.isEmpty())
        return;

    int width = adjustedRect.getWidth();
    int height = adjustedRect.getHeight();
    int bytesPerPixel = getBytesPerPixel();

    if (bytesPerPixel == 1) {
        // Single-byte pixel
        uint8_t pixelValue = *static_cast<const uint8_t*>(pix);
        for (int y = 0; y < height; ++y) {
            for (int x = 0; x < width; ++x) {
                setPixel(adjustedRect.x + x, adjustedRect.y + y, pixelValue);
            }
        }
    } else {
        // Multi-byte pixel
        size_t pixelSize = bytesPerPixel;
        const uint8_t* pixelData = static_cast<const uint8_t*>(pix);
        for (int y = 0; y < height; ++y) {
            for (int x = 0; x < width; ++x) {
                setPixelData(adjustedRect.x + x, adjustedRect.y + y, pixelData, pixelSize);
            }
        }
    }

    commitBufferChanges();
}

void fillRect(const Rect& r, const void* pix) {
    // Check if the rectangle is empty
    if (r.isEmpty())
        return;

    // Calculate width, height, and bytes per pixel
    int width = r.width();
    int height = r.height();
    int bytesPerPixel = getBytesPerPixel(); // Assume this function returns the bytes per pixel for the pixel buffer

    // Check if the rectangle exceeds the bounds of the pixel buffer and adjust if necessary
    Rect adjustedRect = r;
    if (adjustedRect.x + adjustedRect.width > pixelBufferWidth)
        adjustedRect.width = pixelBufferWidth - adjustedRect.x;
    if (adjustedRect.y + adjustedRect.height > pixelBufferHeight)
        adjustedRect.height = pixelBufferHeight - adjustedRect.y;

    // If the adjusted rectangle is empty, return
    if (adjustedRect.isEmpty())
        return;

    // Recalculate width and height based on the adjusted rectangle
    width = adjustedRect.width;
    height = adjustedRect.height;

    // Pointer to the pixel buffer
    uint8_t* buffer = getPixelBuffer(); // Assume this function returns the pixel buffer pointer

    // Offset to the first pixel in the rectangle
    int offset = adjustedRect.y * pixelBufferWidth * bytesPerPixel + adjustedRect.x * bytesPerPixel;

    // Fill the rectangle
    if (bytesPerPixel == 1) {
        // Single byte per pixel
        uint8_t pixelValue = *static_cast<const uint8_t*>(pix);
        for (int i = 0; i < height; i++) {
            for (int j = 0; j < width; j++) {
                buffer[offset + j] = pixelValue;
            }
            offset += pixelBufferWidth;
        }
    } else {
        // Multiple bytes per pixel
        size_t pixelSize = bytesPerPixel;
        const uint8_t* pixelData = static_cast<const uint8_t*>(pix);
        for (int i = 0; i < height; i++) {
            for (int j = 0; j < width; j++) {
                memcpy(&buffer[offset + j * pixelSize], pixelData, pixelSize);
            }
            offset += pixelBufferWidth * pixelSize;
        }
    }

    // Commit the changes to the pixel buffer
    commitPixelBufferChanges(); // Assume this function commits the changes to the pixel buffer
}

